// adminToken is the configured admin credential the test router guards against.
const adminToken = "test-admin-token"

// openAPIStore opens a fresh temp SQLite store for the api tests.
func openAPIStore(t *testing.T) *store.Store {
	t.Helper()
	dsn := filepath.Join(t.TempDir(), "api.db")
	st, err := store.Open(context.Background(), dsn)
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = st.Close() })
	return st
}

// doRequest fires one request at the handler with an optional Bearer token and
// returns the recorded response.
func doRequest(t *testing.T, h http.Handler, method, path, body, token string) *http.Response {
	t.Helper()
	var r io.Reader
	if body != "" {
		r = strings.NewReader(body)
	}
	req := httptest.NewRequest(method, path, r)
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	return rec.Result()
}

// decodeError pulls the canonical error body out of a response.
func decodeError(t *testing.T, resp *http.Response) errorBody {
	t.Helper()
	var eb errorBody
	if err := json.NewDecoder(resp.Body).Decode(&eb); err != nil {
		t.Fatalf("decode error body: %v", err)
	}
	return eb
}

// TestNew_Routes is the table test for New (AC-2): each of the three routes has
// a happy path and an error path, asserted over a real store + injected Scan.
// The scanLibrary happy case is the S1 joint (deps.Scan called exactly once with
// the parsed id) and the createLibrary happy case proves the one domain call
// actually persisted.
func TestNew_Routes(t *testing.T) {
	st := openAPIStore(t)
	scanCalls := []int64{}
	wantScanResult := scan.Result{LibraryID: 7, Discovered: 2, Persisted: 2, Warnings: []string{"w"}}
	scanStub := func(_ context.Context, libraryID int64) (scan.Result, error) {
		scanCalls = append(scanCalls, libraryID)
		return wantScanResult, nil
	}
	h := New(Deps{AdminToken: adminToken, Store: st, Scan: scanStub, Pairing: pairing.NewService(st, nil)})

	t.Run("create_library_happy", func(t *testing.T) {
		body := `{"module_id":"tv","root_path":"/media/tv","display_name":"TV"}`
		resp := doRequest(t, h, http.MethodPost, "/api/v1/libraries", body, adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusCreated {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusCreated)
		}
		var lr libraryDTO
		if err := json.NewDecoder(resp.Body).Decode(&lr); err != nil {
			t.Fatalf("decode libraryDTO: %v", err)
		}
		if lr.ID <= 0 || lr.ModuleID != "tv" || lr.RootPath != "/media/tv" || lr.DisplayName != "TV" {
			t.Fatalf("libraryDTO = %+v", lr)
		}
		// The one domain call persisted: the library row is in the store.
		lib, err := st.GetLibrary(context.Background(), lr.ID)
		if err != nil {
			t.Fatalf("GetLibrary: %v", err)
		}
		if lib.ModuleID != "tv" || lib.RootPath != "/media/tv" {
			t.Fatalf("persisted library = %+v", lib)
		}
	})

	t.Run("create_library_bad_json", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodPost, "/api/v1/libraries", `{not json`, adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusBadRequest {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusBadRequest)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "bad_request" {
			t.Fatalf("error code = %q, want bad_request", eb.Error.Code)
		}
	})

	t.Run("scan_library_happy_delegates_once_with_parsed_id", func(t *testing.T) {
		scanCalls = nil
		resp := doRequest(t, h, http.MethodPost, "/api/v1/libraries/7/scan", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		if len(scanCalls) != 1 || scanCalls[0] != 7 {
			t.Fatalf("scan calls = %v, want exactly [7] (parse id -> ONE deps.Scan call)", scanCalls)
		}
		var sr scanResponse
		if err := json.NewDecoder(resp.Body).Decode(&sr); err != nil {
			t.Fatalf("decode scanResponse: %v", err)
		}
		if sr.LibraryID != 7 || sr.Discovered != 2 || sr.Persisted != 2 || len(sr.Warnings) != 1 {
			t.Fatalf("scanResponse = %+v, want the stubbed scan.Result", sr)
		}
	})

	t.Run("scan_library_bad_id_not_called", func(t *testing.T) {
		before := len(scanCalls)
		resp := doRequest(t, h, http.MethodPost, "/api/v1/libraries/abc/scan", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusBadRequest {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusBadRequest)
		}
		if len(scanCalls) != before {
			t.Fatalf("deps.Scan was called on a bad id; calls went %d -> %d", before, len(scanCalls))
		}
	})

	t.Run("list_items_happy", func(t *testing.T) {
		libID, err := st.CreateLibrary(context.Background(), "tv", "/media/seed", "Seed")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		seed := store.Item{
			ID: "itm_seed_1", ModuleID: "tv", LibraryID: libID, FileID: "fid-1",
			RelativePath: "Show S01E01.mkv", MediaType: "tv",
			Document:      json.RawMessage(`{"title":"Show"}`),
			SchemaVersion: 1,
		}
		if err := st.PutItem(context.Background(), seed); err != nil {
			t.Fatalf("PutItem: %v", err)
		}
		resp := doRequest(t, h, http.MethodGet, "/api/v1/items?library="+strconv.FormatInt(libID, 10), "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		var ir itemsResponse
		if err := json.NewDecoder(resp.Body).Decode(&ir); err != nil {
			t.Fatalf("decode itemsResponse: %v", err)
		}
		if len(ir.Items) != 1 || ir.Items[0].FileID != "fid-1" || ir.Items[0].MediaType != "tv" {
			t.Fatalf("itemsResponse = %+v", ir)
		}
		if ir.Items[0].Status != "new" {
			t.Errorf("items[0].Status = %q, want new (additive status field, column default)", ir.Items[0].Status)
		}
	})

	t.Run("list_items_bad_library", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/items?library=abc", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusBadRequest {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusBadRequest)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "bad_request" {
			t.Fatalf("error code = %q, want bad_request", eb.Error.Code)
		}
	})

	t.Run("list_libraries", func(t *testing.T) {
		// Two freshly created libraries with distinct (module_id, root_path)
		// pairs (the table has a UNIQUE constraint on that pair, and earlier
		// subtests already seeded ("tv","/media/tv") and ("tv","/media/seed")).
		idA, err := st.CreateLibrary(context.Background(), "tv", "/media/tv/list", "TV List")
		if err != nil {
			t.Fatalf("CreateLibrary A: %v", err)
		}
		idB, err := st.CreateLibrary(context.Background(), "film", "/media/film", "Film")
		if err != nil {
			t.Fatalf("CreateLibrary B: %v", err)
		}
		resp := doRequest(t, h, http.MethodGet, "/api/v1/libraries", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		var lr librariesResponse
		if err := json.NewDecoder(resp.Body).Decode(&lr); err != nil {
			t.Fatalf("decode librariesResponse: %v", err)
		}
		// The two created here must round-trip with full fields. (Earlier
		// subtests seeded more, so Items has at least these two.)
		byID := map[int64]libraryDTO{}
		for _, l := range lr.Items {
			byID[l.ID] = l
		}
		for _, want := range []libraryDTO{{ID: idA, ModuleID: "tv", RootPath: "/media/tv/list", DisplayName: "TV List"},
			{ID: idB, ModuleID: "film", RootPath: "/media/film", DisplayName: "Film"}} {
			got, ok := byID[want.ID]
			if !ok {
				t.Fatalf("library id %d missing from response items %v", want.ID, lr.Items)
			}
			if got.ModuleID != want.ModuleID || got.RootPath != want.RootPath || got.DisplayName != want.DisplayName {
				t.Errorf("library id %d = %+v, want %+v (boundary round-trip)", want.ID, got, want)
			}
		}
		// Ordering guarantee from store.ListLibraries: id ASC end-to-end.
		for i := 1; i < len(lr.Items); i++ {
			if lr.Items[i-1].ID >= lr.Items[i].ID {
				t.Fatalf("libraries not id ASC: %+v", lr.Items)
			}
		}
	})

	t.Run("list_libraries_empty", func(t *testing.T) {
		// A fresh store yields the empty-list JSON contract: {"items":[]}
		// (INV-empty-items-array), NOT {"items":null}.
		emptySt := openAPIStore(t)
		emptyH := New(Deps{AdminToken: adminToken, Store: emptySt, Scan: func(context.Context, int64) (scan.Result, error) {
			return scan.Result{}, nil
		}})
		resp := doRequest(t, emptyH, http.MethodGet, "/api/v1/libraries", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		// Raw decode into a map to assert the JSON literal is `[]` not `null`.
		var raw map[string]json.RawMessage
		if err := json.NewDecoder(resp.Body).Decode(&raw); err != nil {
			t.Fatalf("decode raw: %v", err)
		}
		items, ok := raw["items"]
		if !ok {
			t.Fatalf("response missing items key: %v", raw)
		}
		if string(items) != "[]" {
			t.Fatalf("empty-store items = %s, want [] (not null)", string(items))
		}
	})

	t.Run("get_item_full_document", func(t *testing.T) {
		// Seed a ready item with a full §3.1-shaped document (sources/<plugin>,
		// _view, _provenance, _stages) and assert the detail endpoint returns
		// the FULL document byte-for-byte (INV-full-document — no field dropped,
		// precision preserved). id is a string UUID, NOT integer-parsed.
		libID, err := st.CreateLibrary(context.Background(), "tv", "/media/get-item", "GetItem")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		const itemID = "itm-get-item-full"
		doc := json.RawMessage(`{
  "sources": {"base-scanner": {"title": "Show", "year": 2024}},
  "_view": {"title": "Show (2024)"},
  "_provenance": {"base-scanner": {"stage": "identify", "at": "2026-08-05T00:00:00Z"}},
  "_stages": ["identify"]
}`)
		if err := st.PutItem(context.Background(), store.Item{
			ID: itemID, ModuleID: "tv", LibraryID: libID, FileID: "fid-get-item",
			RelativePath: "Show S01E01.mkv", MediaType: "tv",
			Document: doc, SchemaVersion: 1,
		}); err != nil {
			t.Fatalf("PutItem: %v", err)
		}
		resp := doRequest(t, h, http.MethodGet, "/api/v1/items/"+itemID, "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		var ir itemResponse
		if err := json.NewDecoder(resp.Body).Decode(&ir); err != nil {
			t.Fatalf("decode itemResponse: %v", err)
		}
		if ir.Item.ID != itemID || ir.Item.FileID != "fid-get-item" || ir.Item.MediaType != "tv" {
			t.Fatalf("itemResponse identity fields = %+v", ir.Item)
		}
		// Deep-equal on the document: re-marshal both sides to canonical JSON
		// so key-order independence does not cause a false failure.
		wantCanon, _ := json.Marshal(doc)
		got, _ := json.Marshal(ir.Item.Document)
		wantVal, gotVal := map[string]json.RawMessage{}, map[string]json.RawMessage{}
		if err := json.Unmarshal(wantCanon, &wantVal); err != nil {
			t.Fatalf("unmarshal want: %v", err)
		}
		if err := json.Unmarshal(got, &gotVal); err != nil {
			t.Fatalf("unmarshal got: %v", err)
		}
		if len(wantVal) != len(gotVal) {
			t.Fatalf("document top-level keys: got %d, want %d (full document)", len(gotVal), len(wantVal))
		}
		for k, wantV := range wantVal {
			gotV, ok := gotVal[k]
			if !ok {
				t.Errorf("document key %q dropped (INV-full-document)", k)
				continue
			}
			if !bytes.Equal(gotV, wantV) {
				t.Errorf("document key %q = %s, want %s", k, gotV, wantV)
			}
		}
	})

	t.Run("get_item_not_found", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/items/nonexistent-id", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusNotFound {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusNotFound)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "not_found" {
			t.Fatalf("error code = %q, want not_found", eb.Error.Code)
		}
	})

	// Device-pairing mount (device-pairing D2): the pair group is the ONLY
	// unauthenticated API surface — both routes answer with NO Authorization
	// header — while every other group still 401s a tokenless request.
	t.Run("pair_routes_answer_without_token", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodPost, "/api/v1/pair", "", "")
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("POST /pair status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		var pr pairCreateResponse
		if err := json.NewDecoder(resp.Body).Decode(&pr); err != nil {
			t.Fatalf("decode pairCreateResponse: %v", err)
		}
		if pr.PairingID == "" || pr.Code == "" {
			t.Fatalf("pairCreateResponse = %+v (want pairing_id + code)", pr)
		}
		wait := doRequest(t, h, http.MethodGet, "/api/v1/pair/"+pr.PairingID+"/wait", "", "")
		defer wait.Body.Close()
		if wait.StatusCode != http.StatusOK {
			t.Fatalf("GET /pair/{id}/wait status = %d, want %d", wait.StatusCode, http.StatusOK)
		}
		var wr pairWaitResponse
		if err := json.NewDecoder(wait.Body).Decode(&wr); err != nil {
			t.Fatalf("decode pairWaitResponse: %v", err)
		}
		if wr.Status != "pending" || wr.DeviceToken != "" {
			t.Fatalf("pairWaitResponse = %+v (want pending, no token)", wr)
		}
	})

	t.Run("authed_routes_still_401_without_token", func(t *testing.T) {
		for _, rr := range []struct{ method, path string }{
			{http.MethodGet, "/api/v1/libraries"},
			{http.MethodGet, "/api/v1/admin/status"},
			{http.MethodGet, "/api/v1/admin/pairings"},
		} {
			resp := doRequest(t, h, rr.method, rr.path, "", "")
			resp.Body.Close()
			if resp.StatusCode != http.StatusUnauthorized {
				t.Fatalf("%s %s without token: status = %d, want %d", rr.method, rr.path, resp.StatusCode, http.StatusUnauthorized)
			}
		}
	})
}

// TestListItems_StatusFilter is the joint test for seam S11 (api ?status= ->
// store.QueryItems status filter) + the additive status response field. It seeds
// items of distinct statuses and asserts the optional ?status= filters at the
// store boundary, absent/empty returns all (INV-empty-all), and every itemDTO
// round-trips its status.
func TestListItems_StatusFilter(t *testing.T) {
	st := openAPIStore(t)
	libID, err := st.CreateLibrary(context.Background(), "tv", "/media/tv", "TV")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	seedStatus := map[string]string{
		"fid-enriched": "enriched",
		"fid-new":      "new",
		"fid-failed":   "failed",
	}
	for fid, status := range seedStatus {
		if err := st.PutItem(context.Background(), store.Item{
			ID: "itm_" + fid, ModuleID: "tv", LibraryID: libID, FileID: fid,
			RelativePath: fid + ".mkv", MediaType: "tv",
			Document: json.RawMessage(`{}`), SchemaVersion: 1, Status: status,
		}); err != nil {
			t.Fatalf("PutItem %s: %v", fid, err)
		}
	}
	h := New(Deps{AdminToken: adminToken, Store: st, Scan: func(context.Context, int64) (scan.Result, error) {
		return scan.Result{}, nil
	}})

	base := "/api/v1/items?library=" + strconv.FormatInt(libID, 10)
	cases := []struct {
		name string
		path string
		want map[string]string // fileID -> expected status (also the expected set)
	}{
		{"no_status_returns_all", base, seedStatus},
		{"empty_status_returns_all", base + "&status=", seedStatus},
		{"status_enriched_filters", base + "&status=enriched", map[string]string{"fid-enriched": "enriched"}},
		{"status_failed_filters", base + "&status=failed", map[string]string{"fid-failed": "failed"}},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			resp := doRequest(t, h, http.MethodGet, tc.path, "", adminToken)
			defer resp.Body.Close()
			if resp.StatusCode != http.StatusOK {
				t.Fatalf("status = %d, want 200", resp.StatusCode)
			}
			var ir itemsResponse
			if err := json.NewDecoder(resp.Body).Decode(&ir); err != nil {
				t.Fatalf("decode itemsResponse: %v", err)
			}
			got := map[string]string{}
			for _, it := range ir.Items {
				got[it.FileID] = it.Status
			}
			if len(got) != len(tc.want) {
				t.Fatalf("got items %v, want %v", got, tc.want)
			}
			for fid, wantStatus := range tc.want {
				s, ok := got[fid]
				if !ok {
					t.Errorf("missing %q in response (got %v)", fid, got)
					continue
				}
				if s != wantStatus {
					t.Errorf("item %q status = %q, want %q (status field must round-trip)", fid, s, wantStatus)
				}
			}
		})
	}
}
